package server

// Stable OAuth error codes translated without returning upstream credential bodies.
func init() {
	errCatalog["oauth_expired"] = map[string]string{"en": "This sign-in attempt expired or was already used. Start again from model settings.", "ko": "로그인 요청이 만료되었거나 이미 사용되었습니다. 모델 설정에서 다시 시작하세요.", "zh": "此登录请求已过期或已使用。请从模型设置重新开始。", "es": "Este intento de inicio de sesión caducó o ya se usó. Vuelve a empezar desde los ajustes del modelo.", "ja": "ログインの試行が期限切れか使用済みです。モデル設定からやり直してください。"}
	errCatalog["oauth_invalid_request"] = map[string]string{"en": "The connection request is invalid. Return to model settings and try again.", "ko": "연결 요청이 올바르지 않습니다. 모델 설정에서 다시 시도하세요.", "zh": "连接请求无效。请返回模型设置重试。", "es": "La solicitud de conexión no es válida. Vuelve a los ajustes del modelo e inténtalo de nuevo.", "ja": "接続リクエストが無効です。モデル設定から再試行してください。"}
	errCatalog["oauth_unavailable"] = map[string]string{"en": "Connection settings are unavailable. The backend may need to be updated.", "ko": "연결 설정을 불러올 수 없습니다. 백엔드 업데이트가 필요할 수 있습니다.", "zh": "无法加载连接设置。可能需要更新后端。", "es": "Los ajustes de conexión no están disponibles. Puede ser necesario actualizar el backend.", "ja": "接続設定を取得できません。バックエンドの更新が必要な場合があります。"}
	errCatalog["oauth_try_again"] = map[string]string{"en": "Too many pending sign-in attempts. Wait a few minutes and retry.", "ko": "진행 중인 로그인 요청이 너무 많습니다. 잠시 후 다시 시도하세요.", "zh": "待处理的登录请求过多。请稍后重试。", "es": "Hay demasiados intentos de inicio de sesión pendientes. Espera unos minutos y reinténtalo.", "ja": "ログインの試行が多すぎます。数分待ってから再試行してください。"}
	errCatalog["oauth_save_failed"] = map[string]string{"en": "Could not save the model profile. Check the local storage and try again.", "ko": "모델 프로파일을 저장하지 못했습니다. 로컬 저장소를 확인하고 다시 시도하세요.", "zh": "无法保存模型配置。请检查本地存储并重试。", "es": "No se pudo guardar el perfil del modelo. Comprueba el almacenamiento local y reinténtalo.", "ja": "モデルプロファイルを保存できません。ローカルの保存先を確認して再試行してください。"}
	errCatalog["oauth_exchange_failed"] = map[string]string{"en": "Could not complete the connection. Return to model settings and try again.", "ko": "연결을 완료하지 못했습니다. 모델 설정에서 다시 시도하세요.", "zh": "无法完成连接。请返回模型设置重试。", "es": "No se pudo completar la conexión. Vuelve a los ajustes del modelo e inténtalo de nuevo.", "ja": "接続を完了できませんでした。モデル設定に戻って再試行してください。"}
	errCatalog["chatgpt_storage_failed"] = map[string]string{"en": "Could not read or save the protected ChatGPT connection. Check the runtime directory and its original encryption key.", "ko": "보호된 ChatGPT 연결 정보를 읽거나 저장하지 못했습니다. 런타임 경로와 기존 암호화 키 보존 여부를 확인하세요.", "zh": "无法读取或保存受保护的 ChatGPT 连接。请检查运行目录和原始加密密钥。", "es": "No se pudo leer o guardar la conexión protegida de ChatGPT. Comprueba el directorio y la clave de cifrado original.", "ja": "保護された ChatGPT 接続を読み取りまたは保存できません。保存先と元の暗号化キーを確認してください。"}
	errCatalog["chatgpt_reconnect_required"] = map[string]string{"en": "Reconnect this ChatGPT account", "ko": "ChatGPT 계정 재연결 필요", "zh": "请重新连接此 ChatGPT 账号", "es": "Vuelve a conectar esta cuenta de ChatGPT", "ja": "ChatGPT アカウントの再接続が必要です"}
	errCatalog["chatgpt_exchange_failed"] = map[string]string{"en": "Could not complete the connection. Return to model settings and try again.", "ko": "연결을 완료하지 못했습니다. 모델 설정에서 다시 시도하세요.", "zh": "无法完成连接。请返回模型设置重试。", "es": "No se pudo completar la conexión. Vuelve a los ajustes del modelo e inténtalo de nuevo.", "ja": "接続を完了できませんでした。モデル設定に戻って再試行してください。"}
	errCatalog["chatgpt_models_failed"] = map[string]string{"en": "Could not load ChatGPT models. Check the connection and retry.", "ko": "ChatGPT 모델을 가져오지 못했습니다. 연결 상태를 확인하고 다시 시도하세요.", "zh": "无法获取 ChatGPT 模型。请检查连接并重试。", "es": "No se pudieron cargar los modelos de ChatGPT. Comprueba la conexión y reinténtalo.", "ja": "ChatGPT モデルを取得できません。接続を確認して再試行してください。"}
	errCatalog["chatgpt_scope_missing"] = map[string]string{"en": "ChatGPT plan usage was not authorized. Reconnect and grant plan access.", "ko": "ChatGPT 플랜 사용 권한이 승인되지 않았습니다. 다시 연결하고 플랜 사용을 허용하세요.", "zh": "未授权使用 ChatGPT 套餐。请重新连接并授权。", "es": "No se autorizó el uso del plan de ChatGPT. Reconecta y concede acceso al plan.", "ja": "ChatGPT プランの利用が許可されていません。再接続して利用を許可してください。"}
	errCatalog["chatgpt_localhost_required"] = map[string]string{"en": "Sign in from localhost on the computer running ARTEX. Remote browser sign-in is not supported.", "ko": "ARTEX를 실행하는 컴퓨터의 localhost에서 로그인하세요. 다른 컴퓨터의 브라우저 로그인은 지원하지 않습니다.", "zh": "请在运行 ARTEX 的计算机上通过 localhost 登录。不支持远程浏览器登录。", "es": "Inicia sesión desde localhost en el equipo que ejecuta ARTEX. No se admite un navegador remoto.", "ja": "ARTEX を実行しているコンピューターの localhost からログインしてください。別のコンピューターのブラウザーには対応していません。"}
	errCatalog["chatgpt_callback_unavailable"] = map[string]string{"en": "Could not open the sign-in callback. Check that port 8789 is available and published for Docker.", "ko": "로그인 콜백을 열지 못했습니다. 8789 포트 사용 여부와 Docker 포트 게시 설정을 확인하세요.", "zh": "无法打开登录回调。请检查 8789 端口是否可用以及 Docker 端口映射。", "es": "No se pudo abrir el retorno de inicio de sesión. Comprueba el puerto 8789 y su publicación en Docker.", "ja": "ログインのコールバックを開始できません。8789 ポートと Docker の公開設定を確認してください。"}
	errCatalog["chatgpt_select_model"] = map[string]string{"en": "Load the available ChatGPT models again and select a model and profile name.", "ko": "사용 가능한 ChatGPT 모델을 다시 가져와 모델과 프로파일 이름을 선택하세요.", "zh": "请重新获取 ChatGPT 模型并选择模型及配置名称。", "es": "Vuelve a cargar los modelos de ChatGPT y elige un modelo y un nombre de perfil.", "ja": "ChatGPT モデルを再取得し、モデルとプロファイル名を選択してください。"}
	errCatalog["chatgpt_profile_managed"] = map[string]string{"en": "This profile uses its linked ChatGPT account. Authentication and the connection address are managed in the ChatGPT section.", "ko": "연결된 ChatGPT 계정을 사용하는 프로파일입니다. 인증과 연결 주소는 ChatGPT 연결에서 관리합니다.", "zh": "此配置使用关联的 ChatGPT 账号。认证和连接地址由 ChatGPT 连接管理。", "es": "Este perfil usa la cuenta de ChatGPT vinculada. La autenticación y la dirección se gestionan en la sección de ChatGPT.", "ja": "このプロファイルは接続済みの ChatGPT アカウントを使用します。認証と接続先は ChatGPT 接続で管理します。"}
	errCatalog["chatgpt_endpoint_invalid"] = map[string]string{"en": "This profile uses its linked ChatGPT account. Authentication and the connection address are managed in the ChatGPT section.", "ko": "연결된 ChatGPT 계정을 사용하는 프로파일입니다. 인증과 연결 주소는 ChatGPT 연결에서 관리합니다.", "zh": "此配置使用关联的 ChatGPT 账号。认证和连接地址由 ChatGPT 连接管理。", "es": "Este perfil usa la cuenta de ChatGPT vinculada. La autenticación y la dirección se gestionan en la sección de ChatGPT.", "ja": "このプロファイルは接続済みの ChatGPT アカウントを使用します。認証と接続先は ChatGPT 接続で管理します。"}
	errCatalog["chatgpt_request_invalid"] = map[string]string{"en": "The ChatGPT request requires streaming with response storage disabled.", "ko": "ChatGPT 요청은 응답 저장을 끈 스트리밍 방식이어야 합니다.", "zh": "ChatGPT 请求必须启用流式传输并禁用响应存储。", "es": "La solicitud de ChatGPT requiere streaming sin almacenar la respuesta.", "ja": "ChatGPT リクエストには応答の保存を無効にしたストリーミングが必要です。"}
	errCatalog["chatgpt_request_failed"] = map[string]string{"en": "The ChatGPT request could not be completed. Check connectivity.", "ko": "ChatGPT 요청을 완료하지 못했습니다. 연결 상태를 확인하세요.", "zh": "无法完成 ChatGPT 请求。请检查连接。", "es": "No se pudo completar la solicitud de ChatGPT. Comprueba la conexión.", "ja": "ChatGPT リクエストを完了できません。接続を確認してください。"}
	errCatalog["chatgpt_response_failed"] = map[string]string{"en": "ChatGPT reported a failed response. Review the account connection and usage settings.", "ko": "ChatGPT 응답이 실패했습니다. 계정 연결과 사용량 설정을 확인하세요.", "zh": "ChatGPT 响应失败。请检查账号连接和用量设置。", "es": "ChatGPT indicó un fallo de respuesta. Revisa la conexión de la cuenta y los ajustes de uso.", "ja": "ChatGPT の応答が失敗しました。アカウントの接続と使用量設定を確認してください。"}
	errCatalog["chatgpt_response_incomplete"] = map[string]string{"en": "The ChatGPT stream ended before completion. Partial output is not a successful result.", "ko": "ChatGPT 응답이 완료되기 전에 종료되었습니다. 일부 출력만으로 성공 처리하지 않습니다.", "zh": "ChatGPT 流在完成前结束。部分输出不算成功结果。", "es": "El flujo de ChatGPT terminó antes de completarse. La salida parcial no se considera un resultado correcto.", "ja": "ChatGPT の応答が完了前に終了しました。部分的な出力は成功として扱いません。"}
	errCatalog["subscription_sharing_usage_limit_exceeded"] = map[string]string{"en": "ChatGPT usage limit reached. Open Manage usage to review your plan or this app’s limit.", "ko": "ChatGPT 사용 한도에 도달했습니다. 사용량 관리에서 플랜 또는 앱 한도를 확인하세요.", "zh": "已达到 ChatGPT 使用限额。请打开用量管理查看套餐或应用限额。", "es": "Se alcanzó el límite de uso de ChatGPT. Abre Gestionar uso para revisar el límite del plan o de la aplicación.", "ja": "ChatGPT の使用上限に達しました。使用量管理でプランまたはアプリの上限を確認してください。"}
	errCatalog["subscription_sharing_usage_unavailable"] = map[string]string{"en": "ChatGPT plan usage is currently unavailable. Open Manage usage to review your plan settings.", "ko": "현재 ChatGPT 플랜을 사용할 수 없습니다. 사용량 관리에서 플랜 설정을 확인하세요.", "zh": "ChatGPT 套餐用量暂时不可用。请打开用量管理检查套餐设置。", "es": "El uso del plan de ChatGPT no está disponible. Abre Gestionar uso para revisar los ajustes del plan.", "ja": "ChatGPT プランを現在利用できません。使用量管理でプラン設定を確認してください。"}
}
